pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposits) public {
        // Restrict to a range that doesn't overflow and is feasible
        bound(deposits, 1, 1000);

        // Deploy a receiver that always reverts on value transfers
        RevertingReceiver receiver = new RevertingReceiver();

        // Fund the contract
        for (uint256 i = 0; i < deposits; i++) {
            vm.deal(address(this), 1 ether);
            (bool sent,) = address(c).call{value: 1 ether}("");
            require(sent, "deposit failed");
        }
        uint256 contractBal = address(c).balance;
        require(contractBal > 0, "no balance");

        // Owner sends the entire balance to the reverting receiver;
        // the low-level call returns true (RevertingReceiver's fallback is nonpayable, so it reverts, but the call does not revert because require check is after call;
        // actually, to get the scenario where sendMoney succeeds but the external call fails, we need a callee that reverts and the call propagates,
        // but wait: sendMoney has require(__sent_result100) — if the external call fails and returns false, require reverts. So sendMoney cannot succeed with a failing call.
        // The mutation is about withdrawAll, not sendMoney. The invariant: after withdrawAll, the contract balance must be zero in reference.
        // WithdrawAll is onlyOwner, caller is owner (deployer).
        // So just call withdrawAll and check balance.
        c.withdrawAll();

        // Reference contract's withdrawAll calls withdraw(address(this).balance) -> drains all Ether.
        // Buggy contract's withdrawAll calls withdraw(0) -> leaves balance untouched.
        // So after withdrawAll, reference has balance 0, buggy has contractBal.
        assertTrue(address(c).balance == 0);
    }
}

contract RevertingReceiver {
    // nonpayable fallback — any value transfer reverts
    fallback() external { revert("reverting"); }
}

