    function testFuzz_property(uint256 _value) public {
        // Restrict to values the contract can actually hold – keep domain wide.
        _value = bound(_value, 0, 1_000_000 ether);
        // Fund the contract with exactly _value so withdraw doesn't revert due to insufficient balance.
        vm.deal(address(c), _value);
        // Give the owner some ether to pay for gas; owner must be the caller.
        address owner = c.owner();
        vm.deal(owner, 10 ether);
        // Record contract balance before the withdraw call.
        uint256 balBefore = address(c).balance;
        // Owner calls withdraw.
        vm.prank(owner);
        c.withdraw(_value);
        // Record contract balance after.
        uint256 balAfter = address(c).balance;
        // For the reference contract, balBefore == _value (since we just funded it) and balAfter ≈ 0.
        // For the mutant, balAfter remains _value (minus gas, which is negligible compared to _value).
        // The rule: after withdrawal, the contract balance must be strictly less than _value.
        // This holds for the reference (it sends _value), and fails for the mutant (it sends 0, so balAfter ≈ _value).
        assertTrue(balAfter < _value);
    }
}

